-- Translate only university descriptions that already have an English source text.
-- Empty descriptions remain empty and continue to use the reviewed-data placeholder.
-- Generated: 2026-10-09

WITH translations(slug, description_zh) AS (
    VALUES
        ('local-preview-university-of-oxford', '牛津大学是位于英格兰牛津的学院制研究型大学。早在1096年便已有教学活动的记录，使其成为英语世界历史最悠久的大学，也是世界上持续办学时间第二长的大学。1167年，英格兰国王亨利二世禁止英格兰学生就读巴黎大学后，牛津大学迅速发展。后来，由于学生与牛津当地居民之间的冲突加剧，部分牛津学者前往剑桥，并于1209年创立剑桥大学。两所大学具有许多共同特点，合称“牛剑”。'),
        ('local-preview-university-of-cambridge', '剑桥大学是世界领先的大学之一，其突破性思想与学术创新的悠久历史可追溯至1209年。'),
        ('local-preview-university-college-london', '伦敦大学学院通常以UCL之名开展办学，是位于英格兰伦敦的公立研究型大学，也是伦敦大学联盟的成员院校。按学生总人数计算，UCL是英国规模第二大的大学；按研究生人数计算，则是英国规模最大的大学。'),
        ('local-preview-university-of-bristol', '布里斯托大学是位于英格兰布里斯托的公立研究型大学，于1909年获得皇家特许状，其办学历史可追溯至1876年成立的布里斯托大学学院。成立于1833年的布里斯托医学院于1893年并入该学院，后来成为大学的医学院。'),
        ('local-preview-university-of-warwick', '华威大学是英国领先的大学之一，提供涵盖人文艺术、科学、工程和社会科学等领域的本科及研究生课程。'),
        ('local-preview-durham-university', '杜伦大学是位于英格兰杜伦的学院制公立研究型大学。学校依据1832年的议会法案创立，并于1837年获得皇家特许状。它是牛津和剑桥之后六百多年间英格兰首所获正式承认并开办的大学，因此被一些历史学者称为英格兰第三古老的大学。作为学院制大学，其主要职能由大学的学术院系与17所学院共同承担：院系主要负责研究与教学，学院则主要负责学生生活安排与福利支持。'),
        ('local-preview-queen-mary-university-of-london', '伦敦玛丽女王大学是位于英格兰东伦敦麦尔安德的公立研究型大学，也是伦敦大学联盟成员。学校同时是英国研究密集型大学罗素集团、英联邦大学协会和英国大学协会的成员。'),
        ('local-preview-johns-hopkins-university', '约翰斯·霍普金斯大学（JHU，常简称Hopkins）是位于美国马里兰州巴尔的摩的私立研究型大学。学校于1867年注册成立，并于1876年参照欧洲研究机构模式开办，通常被认为是美国第一所研究型大学。'),
        ('local-preview-princeton-university', '普林斯顿大学是位于美国新泽西州普林斯顿的私立常春藤盟校研究型大学。学校于1746年以“新泽西学院”之名在伊丽莎白创立，是美国历史第四悠久的高等教育机构，也是美国独立战争前获特许成立的九所殖民地学院之一。学校于1747年迁至纽瓦克，九年后迁至普林斯顿的默瑟县校址；1896年正式升格为大学，并更名为普林斯顿大学。'),
        ('local-preview-columbia-university', '纽约市哥伦比亚大学通常简称哥伦比亚大学，是位于美国纽约市的私立常春藤盟校研究型大学。学校于1754年依据英国国王乔治二世的皇家特许状，以“国王学院”之名在曼哈顿三一教堂所在地创立，是纽约州历史最悠久、美国历史第五悠久的高等教育机构。'),
        ('local-preview-university-of-michigan-ann-arbor', '密歇根大学是位于美国密歇根州安娜堡的公立研究型大学，创立于1817年，是该州历史最悠久的高等教育机构。学校也是美国较早建立的研究型大学之一，并为美国大学协会的创始成员。'),
        ('local-preview-carnegie-mellon-university', '卡内基梅隆大学。'),
        ('local-preview-university-of-melbourne', '墨尔本大学是位于澳大利亚墨尔本的公立研究型大学，创立于1853年，是澳大利亚历史第二悠久、维多利亚州历史最悠久的大学。主校区位于墨尔本中央商务区以北的帕克维尔，此外在维多利亚州各地设有多个校区。'),
        ('local-preview-monash-university', '莫纳什大学是以澳大利亚维多利亚州墨尔本为基地的公立研究型大学，以第一次世界大战时期的将领约翰·莫纳什爵士命名，创立于1958年。学校设有多个校区，其中四个位于维多利亚州，另有校区位于马来西亚和印度尼西亚；此外还在意大利普拉托设有研究与教学中心，在印度孟买设有研究生研究学院，并在中国苏州和印度尼西亚丹格朗设有研究生院。'),
        ('local-preview-adelaide-university', '阿德莱德大学是澳大利亚的一所公立大学，由原阿德莱德大学与南澳大学合并组建，于2026年正式成立。'),
        ('local-preview-rmit-university', '皇家墨尔本理工大学（RMIT）是一所以技术、设计和企业创新为特色的国际化大学。'),
        ('local-preview-macquarie-university', '麦考瑞大学是位于澳大利亚新南威尔士州悉尼的公立研究型大学。学校由新南威尔士州政府于1964年创立，是悉尼都会区设立的第三所大学。'),
        ('local-preview-deakin-university', '迪肯大学是位于澳大利亚维多利亚州的公立研究型大学。其最大校区位于州首府墨尔本，并在吉朗和瓦南布尔设有地区校区。学校以澳大利亚早期总理、澳大利亚联邦奠基人之一阿尔弗雷德·迪肯命名。'),
        ('local-preview-griffith-university', '格里菲斯大学是位于澳大利亚昆士兰州东南部的公立研究型大学，创立于1971年，并于1975年正式开学。学校在黄金海岸、内森、洛根、南岸和芒特格拉瓦特设有五个校区，位于布里斯班中央商务区财政大楼的第六个校区计划于2027年启用。学校以塞缪尔·沃克·格里菲斯爵士命名，他曾两度担任昆士兰州总理，并出任澳大利亚高等法院首任首席大法官。'),
        ('local-preview-queensland-university-of-technology', '昆士兰科技大学（QUT）是位于澳大利亚昆士兰州布里斯班的公立研究型大学，主要设有花园角市中心校区和凯尔文格罗夫校区。学校开设建筑、工程、信息技术、健康、教育、法律、艺术与设计、科学及数学等领域的课程。'),
        ('local-preview-la-trobe-university', '拉筹伯大学是以澳大利亚维多利亚州墨尔本为基地的公立研究型大学，主校区位于班杜拉。学校于1964年成立，是维多利亚州第三所、澳大利亚第十二所大学，也是澳大利亚“绿野大学”之一和创新研究型大学联盟成员。'),
        ('local-preview-university-of-newcastle', '纽卡斯尔大学是位于澳大利亚新南威尔士州纽卡斯尔的公立大学，创立于1965年，主校区位于纽卡斯尔郊区卡拉汉。学校还在中央海岸、新加坡、纽卡斯尔中央商务区和悉尼设有校区。'),
        ('local-preview-university-of-tasmania', '塔斯马尼亚大学（UTAS）是主要位于澳大利亚塔斯马尼亚州的公立研究型大学，创立于1890年，是澳大利亚历史第四悠久的大学。其住宿学院之一基督学院的设立构想于1840年首次提出，并以牛津和剑桥的学院为范本，于1846年创立，被认为是澳大利亚历史最悠久的高等教育机构。塔斯马尼亚大学属于澳大利亚砂岩大学，也是英联邦大学协会和东南亚高等教育机构协会成员。'),
        ('local-preview-national-university-of-singapore', '新加坡国立大学（NUS）是新加坡的国立公立研究型大学。学校于1980年由政府推动公立的新加坡大学与私立的南洋大学合并后正式成立。'),
        ('local-preview-singapore-university-of-social-sciences', '新跃社科大学（SUSS）是新加坡的一所公立自治大学，于2017年由新跃大学改组成立，重点发展以社会科学为主的应用型学位课程。'),
        ('local-preview-insead-asia-campus', '欧洲工商管理学院（INSEAD）是一所非营利商学院，在法国枫丹白露、新加坡、阿拉伯联合酋长国和美国设有办学地点。'),
        ('local-preview-essec-asia-pacific', '埃塞克商学院（ESSEC）是法国商学院及大学校，主校区位于塞尔吉，并在巴黎、拉巴特和新加坡设有其他校区。'),
        ('local-preview-sorbonne-assas-asia', '巴黎第二大学（巴黎先贤祠—阿萨斯大学）通常简称阿萨斯大学、阿萨斯或巴黎二大，是位于法国巴黎的公立研究型大学。'),
        ('local-preview-ehl-campus-singapore', '洛桑酒店管理学院（EHL）前身为洛桑旅馆学校，是一所位于瑞士的酒店管理院校。学校在国际酒店与款待管理教育领域具有较高知名度，致力于培养学生从事酒店及款待行业的管理工作。'),
        ('local-preview-james-cook-university-singapore', '詹姆斯库克大学新加坡校区是澳大利亚公立研究型大学詹姆斯库克大学的分校，创立于2003年，目前是新加坡唯一拥有大学地位的海外教育机构。校区位于新加坡中央区加冷与芽笼之间，所在地原为曼殊理中学校址。'),
        ('local-preview-kaplan-singapore', '新加坡楷博高等教育学院提供面向未来的课程体系，并让学生有机会接触世界各地的知名大学课程。课程涵盖新加坡校内学习和在线学位等形式，旨在帮助学生发展个人与职业能力。'),
        ('local-preview-psb-academy', '新加坡PSB学院是一所私立教育机构，提供商业、工程、信息技术和生命科学等领域的文凭、学位及研究生课程。学院配备现代化设施，课程注重行业需求，并由具备相关经验的教师授课，致力于通过创新教学与全面学习体验，培养能够适应未来职业发展的毕业生。')
)
UPDATE universities AS u
SET description_zh = t.description_zh,
    updated_at = CURRENT_TIMESTAMP
FROM translations AS t
WHERE u.slug = t.slug
  AND NULLIF(BTRIM(u.description_en), '') IS NOT NULL;
